<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Order #{{ $order->id }} | Smart Basket</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="{{ asset('css/premium-dark-theme.css') }}"><link rel="stylesheet" href="{{ asset('css/order-tracking.css') }}"></head><body><main class="order-page"><div class="container"><a href="{{ route('orders.index') }}" class="btn btn-outline-primary btn-sm mb-3">← My Orders</a><h1 class="h2 fw-bold mb-4">Order #{{ $order->id }} Tracking</h1><div class="row g-4"><div class="col-lg-7"><section class="order-card"><h2 class="h5 mb-3">Order items</h2>@foreach($order->items ?? [] as $item)@php($product = $products[$item['product_id'] ?? null] ?? null)<div class="order-product mb-3"><img src="{{ $product && $product->image ? asset('products/'.$product->image) : 'https://placehold.co/160x160/1E293B/FFFFFF?text=Product' }}" alt="{{ $item['name'] ?? 'Product' }}"><div><h3 class="h6">{{ $item['name'] ?? $product?->name ?? 'Product' }}</h3><p class="order-meta mb-0">₹{{ number_format((float) ($item['price'] ?? 0), 2) }} · Quantity {{ $item['quantity'] ?? 1 }}</p></div></div>@endforeach</section><section class="tracking-card mt-4"><h2 class="h5">📍 Track Order</h2><div class="tracking-map"><div><i class="fa-solid fa-location-dot"></i><strong>{{ $order->deliveryDetail?->current_location ?? 'Seller Warehouse' }}</strong><small class="d-block">Map and live GPS API integration point</small></div></div>@php($steps = ['Order Placed','Seller Confirmed','Packed','Picked By Delivery Partner','Out For Delivery','Near Customer','Delivered'])@php($current = $order->deliveryDetail?->status ?? $order->order_status ?? 'Order Placed')<ol class="order-timeline">@foreach($steps as $step)<li class=